class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        if (k == 1 || !head) return head;
        ListNode dummy(0);
        dummy.next = head;
        ListNode* prevGroup = &dummy;

        while (true) {
            // Find the k-th node from prevGroup
            ListNode* kth = prevGroup;
            for (int i = 0; i < k && kth; ++i) {
                kth = kth->next;
            }
            if (!kth) break;               // not enough nodes left

            ListNode* nextGroup = kth->next; // node after the k-group
            // Reverse the k nodes
            ListNode* prev = nextGroup;
            ListNode* cur = prevGroup->next;
            while (cur != nextGroup) {
                ListNode* tmp = cur->next;
                cur->next = prev;
                prev = cur;
                cur = tmp;
            }
            // Connect reversed group with previous part
            ListNode* tail = prevGroup->next; // original head becomes tail
            prevGroup->next = kth;            // kth is new head of this group
            prevGroup = tail;                 // move prevGroup to the tail for next iteration
        }
        return dummy.next;
    }
};
